<script setup>
import { onBeforeUnmount,onMounted,ref,watch } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { useInteractionAudio } from '../../composables/useInteractionAudio.js';
import { useLocalDraft } from '../../composables/useLocalDraft.js';
import { defaultTone,tonePresets,effectNames,validateTone,moveEffect,guitarToneKey,parseToneFile } from '../../room/effects.js';
import { createGuitarEffectsEngine,renderToneWav } from '../../audio/guitarEffectsEngine.js';
import { saveLocal,downloadJson } from '../../room/storage.js';
import { recordActivity } from '../../room/activityLog.js';
const {state,saved}=useLocalDraft('hitori-room:effects-draft:v1',defaultTone,validateTone),audio=useInteractionAudio('guitar-effects');
const active=ref(-1),ready=ref(false),busy=ref(false),exporting=ref(false),message=ref('先拨一根弦，再慢慢找到自己的声音。'),dragged=ref(''),fileInput=ref(null);
let alive=true,generation=0,flashTimer,importRevision=0;
const engine=createGuitarEffectsEngine({createContext:()=>{const Audio=window.AudioContext||window.webkitAudioContext;return new Audio();},isHidden:()=>document.hidden});
const strings=[{name:'E₂',hz:82.41},{name:'A₂',hz:110},{name:'D₃',hz:146.83},{name:'G₃',hz:196},{name:'B₃',hz:246.94},{name:'E₄',hz:329.63}];
watch(state,value=>engine.setPreset(value),{deep:true,immediate:true});watch(audio.volume,value=>engine.setVolume(value),{immediate:true});watch(audio.enabled,value=>{if(!value)stop();});
function stop(){generation++;ready.value=false;busy.value=false;engine.stop();active.value=-1;clearTimeout(flashTimer);}
async function sound(index=-1){if(busy.value)return;const token=generation;if(!ready.value){busy.value=true;const [enabled,unlocked]=await Promise.all([audio.setEnabled(true),engine.unlock()]);if(!alive||token!==generation)return;busy.value=false;ready.value=enabled&&unlocked;}if(!ready.value){message.value='声音暂时没有准备好，请再试一次。';return;}if(index<0)strings.forEach((s,i)=>engine.play(s.hz,i*.022));else engine.play(strings[index].hz);active.value=index;clearTimeout(flashTimer);flashTimer=setTimeout(()=>active.value=-1,250);message.value=index<0?'六根弦，一起响起。':`拨响了 ${strings[index].name}，可以边听边调整旋钮。`;}
function shift(id,offset){state.value=moveEffect(state.value,id,offset);}
function drop(id){if(!dragged.value||dragged.value===id)return;const order=[...state.value.order],from=order.indexOf(dragged.value),to=order.indexOf(id);order.splice(to,0,...order.splice(from,1));state.value.order=order;dragged.value='';}
function save(){if(!state.value.name.trim()){message.value='先给这个音色起个名字吧。';return;}const tone=validateTone(state.value);message.value=saveLocal(guitarToneKey,tone)?'音色已保存。编曲台勾选「使用我的吉他音色」即可试听。':'浏览器无法保存，可导出音色 JSON 备份。';recordActivity('effects',tone.name,JSON.stringify(tone));}
async function importTone(event){const file=event.target.files?.[0];if(!file)return;const revision=++importRevision;try{if(file.size>16384)throw new Error('音色文件不能超过 16 KiB。');const tone=parseToneFile(await file.text());if(!alive||revision!==importRevision)return;stop();state.value=tone;message.value='已打开导入的音色。点击保存后才会用于编曲台。';}catch(e){if(alive&&revision===importRevision)message.value=e.message;}finally{if(alive)event.target.value='';}}
async function wav(){if(exporting.value)return;exporting.value=true;message.value='正在生成六秒试听，不会自动播放。';try{const Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext;if(!Offline)throw new Error('当前浏览器不支持离线生成，可以先导出音色 JSON。');const blob=await renderToneWav(state.value,Offline);if(!alive)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='hitori-guitar-tone.wav';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);message.value='六秒 WAV 试听已生成。';}catch(e){if(alive)message.value=e.message;}finally{if(alive)exporting.value=false;}}
function keyboard(event){if(event.repeat||event.ctrlKey||event.metaKey||/INPUT|SELECT|TEXTAREA/.test(event.target.tagName)||event.target.isContentEditable||event.target.closest?.('.room-companion'))return;const index=Number(event.key)-1;if(index>=0&&index<6){event.preventDefault();sound(index);}}
function hidden(){if(document.hidden){stop();message.value='离开页面时已停止试音，返回后可重新拨弦。';}}
onBeforeRouteLeave(stop);
onMounted(()=>{window.addEventListener('keydown',keyboard);document.addEventListener('visibilitychange',hidden);});onBeforeUnmount(()=>{alive=false;stop();engine.dispose();window.removeEventListener('keydown',keyboard);document.removeEventListener('visibilitychange',hidden);});
</script>
<template><section class="room-panel" aria-labelledby="effects-title"><div class="play-heading"><div><p class="play-eyebrow">FIND YOUR OWN TONE / 把声音拧成喜欢的样子</p><h2 id="effects-title">这一根弦，有自己的性格。</h2><p class="room-intro">拨弦、旋转旋钮、交换踏板。所有声音均为本站合成，主动拨弦才会响起。</p></div><span class="play-number" aria-hidden="true">08</span></div>
  <div class="play-toolbar"><button v-for="preset in tonePresets" :key="preset.name" type="button" @click="state=validateTone(preset)">{{preset.name}}</button></div>
  <div class="tone-strings" role="group" aria-label="六根吉他弦"><button v-for="(string,index) in strings" :key="string.name" type="button" :class="{'is-plucked':active===index}" :aria-label="`拨响${string.name}弦，按键${index+1}`" :disabled="busy" @click="sound(index)"><span>{{index+1}}</span><i :style="{height:`${6-index*.7}px`}"></i><strong>{{string.name}}</strong></button></div><div class="room-actions"><button id="effects-strum" type="button" class="primary" :disabled="busy" @click="sound()">{{busy?'准备音效…':'扫一下六根弦'}}</button><button type="button" @click="stop();message='试音已停止。'">停止试音</button><span class="play-footer-note">键盘 1–6 也能拨弦</span></div>
  <div class="effect-chain" aria-label="效果器连接顺序"><span>GUITAR IN →</span><span v-for="id in state.order" :key="id">{{effectNames[id]}}{{state.enabled[id]?' ●':' ○'}} →</span><span>AMP OUT</span></div>
  <div class="effect-pedals"><article v-for="(id,index) in state.order" :key="id" class="effect-pedal" :data-effect="id" :class="{'is-on':state.enabled[id]}" :draggable="true" @dragstart="dragged=id" @dragend="dragged=''" @dragover.prevent @drop.prevent="drop(id)"><header><span>0{{index+1}} / {{id.toUpperCase()}}</span><h3>{{effectNames[id]}}</h3></header><label v-if="id==='drive'" class="effect-knob">失真强度 {{Math.round(state.drive*100)}}%<span :style="{transform:`rotate(${-130+state.drive*260}deg)`}"></span><input id="tone-drive" v-model.number="state.drive" class="play-range" type="range" min="0" max="1" step="0.01"></label><template v-if="id==='delay'"><label>回声间隔 {{Math.round(state.delayTime*1000)}} ms<input v-model.number="state.delayTime" aria-label="回声间隔" class="play-range" type="range" min="0.08" max="0.65" step="0.01"></label><label>反馈 {{Math.round(state.feedback*100)}}%<input v-model.number="state.feedback" class="play-range" type="range" min="0" max="0.65" step="0.01"></label><label>混合 {{Math.round(state.delayMix*100)}}%<input v-model.number="state.delayMix" class="play-range" type="range" min="0" max="0.65" step="0.01"></label></template><label v-if="id==='reverb'" class="effect-knob">空间感 {{Math.round(state.reverbMix*100)}}%<span :style="{transform:`rotate(${-130+state.reverbMix/0.75*260}deg)`}"></span><input v-model.number="state.reverbMix" class="play-range" type="range" min="0" max="0.75" step="0.01"></label><button type="button" class="effect-bypass" :aria-pressed="state.enabled[id]" @click="state.enabled[id]=!state.enabled[id]">{{state.enabled[id]?'● 已接入':'○ 已旁通'}}</button><div class="effect-reorder"><button type="button" :disabled="index===0" :aria-label="`把${effectNames[id]}向前移动`" @click="shift(id,-1)">←</button><button type="button" :disabled="index===2" :aria-label="`把${effectNames[id]}向后移动`" @click="shift(id,1)">→</button></div></article></div>
  <p class="adventure-hint">桌面可拖动踏板交换顺序；手机或键盘可用左右按钮。旋钮直接作用于正在响的声音，交换连接或旁通时会清掉旧的余音。</p><label class="room-field" for="tone-name">给这个音色命名<input id="tone-name" v-model="state.name" maxlength="32"></label><div class="room-actions"><button id="tone-save" type="button" class="primary" @click="save">保存音色供编曲使用</button><RouterLink to="/room/studio" class="room-button">去编曲台试听 ↗</RouterLink><button type="button" @click="downloadJson(validateTone(state),'hitori-guitar-tone.json')">导出音色 JSON</button><button type="button" @click="fileInput.click()">导入音色 JSON</button><input ref="fileInput" type="file" hidden accept=".json,application/json" aria-label="选择音色 JSON 文件" @change="importTone"><button id="tone-wav" type="button" :disabled="exporting" @click="wav">{{exporting?'生成中…':'导出 6 秒试听 WAV ↓'}}</button></div><p class="room-status" role="status">{{message}}</p><p class="play-footer-note">{{saved?'旋钮与连接顺序自动保存在本机。':'浏览器无法保存，可以导出音色配置或 WAV。'}} 全站音效开关和音量对试音同样有效；切后台或离页会停止声音。</p>
</section></template>
<style scoped>.tone-strings{background:#493d4b;border:1px solid #aa8d9e;padding:20px}.tone-strings button{display:flex;width:100%;background:transparent;color:#f0dcbd;align-items:center;gap:20px;border:0;min-height:47px;padding:5px 0}.tone-strings span{font:11px monospace;color:#c2a7b8}.tone-strings strong{font:12px monospace;min-width:34px}.tone-strings i{flex:1;background:linear-gradient(#f2e5c2,#a48b70);border-radius:4px}.tone-strings .is-plucked i{background:#f4b9d0;box-shadow:0 0 12px #f4b9d0}.effect-chain{display:flex;flex-wrap:wrap;gap:10px;font:10px monospace;color:#967187;margin:28px 0 15px}.effect-pedals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.effect-pedal{padding:22px 18px;border:2px solid #bda5b2;background:#eee3d7;box-shadow:0 5px 0 #c3aebb;min-width:0}.effect-pedal.is-on{background:#dfd0dc;border-color:#a57c97}.effect-pedal[data-effect=delay]{background:#d9e3de}.effect-pedal[data-effect=reverb]{background:#d8dbe9}.effect-pedal header>span{font:9px monospace;letter-spacing:2px;color:#826579}.effect-pedal label{display:grid;gap:8px;font-size:11px;margin:16px 0}.effect-pedal input{min-height:32px!important}.effect-knob{text-align:center;min-height:185px;place-items:center}.effect-knob>span{display:block;width:70px;height:70px;border-radius:50%;background:radial-gradient(circle at 30% 25%,#847181,#463747);box-shadow:0 4px 8px #614f6544;border:4px solid #b8a2b1;position:relative}.effect-knob>span::after{content:'';position:absolute;top:2px;left:28px;width:4px;height:19px;background:#f5d89a}.effect-pedal .effect-bypass{width:100%;min-height:48px;background:#635263;color:#fff0dc;border:1px solid #685167}.effect-reorder{display:flex;justify-content:center;gap:10px;margin-top:12px}.effect-reorder button{min-width:44px;padding:6px}.effect-pedal:focus-within{outline:1px solid #b2859e;outline-offset:4px}@media(max-width:640px){.effect-pedals{grid-template-columns:1fr}.effect-pedal{padding:20px}.effect-knob{min-height:160px}.effect-knob>span{width:60px;height:60px}.effect-knob>span::after{left:23px}.effect-pedal label{max-width:100%}}
</style>
